const evt=$input.first().json?.raw_data||$input.first().json;
// Only execute on pre-approved DFIR hosts to prevent misuse
const approved_hosts=['prod-web-01','prod-db-01','prod-api-01']; // pull from DB in prod
const hostname=evt.hostname||evt.host||'';
const is_approved=approved_hosts.includes(hostname)||evt.dfir_authorized===true;
if(!is_approved) throw new Error(`Memory analysis not authorized for host: ${hostname}. Add to approved list.`);
return[{json:{hostname,case_id:evt.case_id||`MEM-${Date.now()}`,
  alert_type:evt.alert_type||'suspicious_process',process_name:evt.process_name||'unknown',
  pid:evt.pid||null,authorized:true,requested_at:new Date().toISOString()}}];

const ctx=$input.first().json;
// Volatility 3 plugin selection based on alert type
const plugin_map={
  'suspicious_process':['windows.pslist','windows.pstree','windows.cmdline','windows.dlllist'],
  'network_anomaly':['windows.netstat','windows.netscan','windows.connections'],
  'rootkit_suspected':['windows.ssdt','windows.idt','windows.callbacks','windows.modules'],
  'credential_access':['windows.lsadump','windows.hashdump','windows.cachedump'],
  'default':['windows.pslist','windows.cmdline','windows.netstat']
};
const plugins=plugin_map[ctx.alert_type]||plugin_map['default'];
return[{json:{...ctx,plugins,plugin_count:plugins.length,
  volatility_cmd:`vol.py -f /proc/kcore ${plugins.join(' ')}`,
  analysis_id:`VOL-${ctx.case_id}`}}];

